### Path Traversal Example:

Consider a Node.js application where you want to allow users to specify a filename for downloading. However, if this input is not validated, an attacker could potentially manipulate the input to access arbitrary files on the server filesystem.

**Vulnerable Code:**
```javascript
const fs = require('fs');
function downloadFile(filename) {
    let filePath = `/path/to/secure/folder/${filename}`;
    fs.readFile(filePath, 'utf-8', (err, data) => {
        if(err) throw new Error("File not found");
        console.log(data);
    });
}
```

### Safe Implementation:

To avoid the path traversal vulnerability, you should validate and sanitize the user-supplied filename to ensure it only references files within a secure directory. Here's how you can do it in Node.js:

**Safe Code:**
```javascript
const fs = require('fs');
function downloadFile(filename) {
    // Define the allowed characters for filenames
    const pattern = /^[a-zA-Z0-9_\-\.]+$/;

    // Validate the filename
    if (!pattern.test(filename)) {
        console.error("Invalid filename");
        return;
    }

    // Create a normalized path with a fixed prefix to prevent traversal attacks
    let filePath = `/path/to/secure/folder/${filename}`;
    filePath = fs.path.normalize(filePath); // Normalize the path to ensure it doesn't go outside the expected directory

    try {
        fs.readFile(filePath, 'utf-8', (err, data) => {
            if(err && err.code === 'ENOENT') {
                console.error("File not found");
            } else {
                console.log(data);
            }
        });
    } catch (e) {
        console.error(e.message);
    }
}
```

